layer.css:
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap");
[data-ryt="pitch"] { color: rgb(55, 65, 81); background-color: rgb(249, 250, 251); border-left: 4px solid rgb(255, 107, 157); border-radius: 0px 12px 12px 0px; box-shadow: rgba(0, 0, 0, 0.1) 0px 1px 3px 0px, rgba(0, 0, 0, 0.06) 0px 1px 2px 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: italic; line-height: 1.625; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(55, 65, 81); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 24px; padding-right: 24px; padding-bottom: 24px; padding-left: 24px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); background-color: rgb(249, 250, 251); border-top: 1px solid var(--ryt-border); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-bg); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 12px; box-shadow: rgba(0, 0, 0, 0.1) 0px 1px 3px 0px, rgba(0, 0, 0, 0.06) 0px 1px 2px 0px; transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #e96493; border-radius: 0px; font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 107, 157); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1; letter-spacing: -2.4px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #838b97; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 500; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(156, 163, 175); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); background-image: linear-gradient(135deg, rgb(255, 107, 157) 0%, rgb(99, 102, 241) 100%); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: -0.5px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; background-clip: text; -webkit-text-fill-color: rgba(0, 0, 0, 0); -webkit-background-clip: text; -webkit-text-fill-color: transparent }
[data-ryt="header"] { border-bottom: 1px solid var(--ryt-border); border-top: none }
[data-ryt="nav"] a { color: #e96493; border-radius: 6px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 107, 157); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="review"] { color: rgb(55, 65, 81); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(55, 65, 81); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; letter-spacing: -0.5px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 600; font-style: normal; line-height: 1.25; letter-spacing: -0.5px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #ff4585; text-decoration-line: underline; text-decoration-style: initial; text-decoration-color: #ffb3d1; text-decoration-thickness: 2px; text-underline-offset: 3px }
[data-ryt="nav"] a:hover { color: #ff4585; text-decoration-line: underline; text-decoration-style: initial; text-decoration-color: #ffb3d1; text-decoration-thickness: 2px; text-underline-offset: 3px }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #ff4585; text-decoration-line: underline; text-decoration-style: initial; text-decoration-color: #ffb3d1; text-decoration-thickness: 2px; text-underline-offset: 3px }
article[data-ryt="rec-card"]:hover { transform: translateY(-4px); box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04) }
